#define Lg2 Lg2__log10
#define Lg3 Lg3__log10
#define Lg4 Lg4__log10
#define Lg5 Lg5__log10
#define Lg6 Lg6__log10
#define Lg7 Lg7__log10
#define R R__log10
/* origin: FreeBSD /usr/src/lib/msun/src/e_log10.c */
