static char sl6610b[57] = " * software is freely granted, provided that this notice";
static const lxl_str sl6610 = {.p = sl6610b, .cap = 0U, .len = 56U};
static char sl6611b[17] = " * is preserved.";
static const lxl_str sl6611 = {.p = sl6611b, .cap = 0U, .len = 16U};
static char sl6612b[12] = "/* expm1(x)";
static const lxl_str sl6612 = {.p = sl6612b, .cap = 0U, .len = 11U};
static char sl6613b[51] = " * Returns exp(x)-1, the exponential of x minus 1.";
static const lxl_str sl6613 = {.p = sl6613b, .cap = 0U, .len = 50U};
static char sl6614b[10] = " * Method";
static const lxl_str sl6614 = {.p = sl6614b, .cap = 0U, .len = 9U};
static char sl6615b[28] = " *   1. Argument reduction:";
static const lxl_str sl6615 = {.p = sl6615b, .cap = 0U, .len = 27U};
static char sl6616b[48] = " *      Given x, find r and integer k such that";
static const lxl_str sl6616 = {.p = sl6616b, .cap = 0U, .len = 47U};
static char sl6617b[58] = " *               x = k*ln2 + r,  |r| <= 0.5*ln2 ~ 0.34658";
static const lxl_str sl6617 = {.p = sl6617b, .cap = 0U, .len = 57U};
static char sl6618b[64] = " *      Here a correction term c will be computed to compensate";
static const lxl_str sl6618 = {.p = sl6618b, .cap = 0U, .len = 63U};
static char sl6619b[64] = " *      the error in r when rounded to a floating-point number.";
static const lxl_str sl6619 = {.p = sl6619b, .cap = 0U, .len = 63U};
static char sl6620b[65] = " *   2. Approximating expm1(r) by a special rational function on";
static const lxl_str sl6620 = {.p = sl6620b, .cap = 0U, .len = 64U};
static char sl6621b[34] = " *      the interval [0,0.34658]:";
static const lxl_str sl6621 = {.p = sl6621b, .cap = 0U, .len = 33U};
static char sl6622b[14] = " *      Since";
static const lxl_str sl6622 = {.p = sl6622b, .cap = 0U, .len = 13U};
static char sl6623b[63] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 - r^4/360 + ...";
static const lxl_str sl6623 = {.p = sl6623b, .cap = 0U, .len = 62U};
static char sl6624b[29] = " *      we define R1(r*r) by";
static const lxl_str sl6624 = {.p = sl6624b, .cap = 0U, .len = 28U};
static char sl6625b[57] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 * R1(r*r)";
static const lxl_str sl6625 = {.p = sl6625b, .cap = 0U, .len = 56U};
static char sl6626b[17] = " *      That is,";
static const lxl_str sl6626 = {.p = sl6626b, .cap = 0U, .len = 16U};
static char sl6627b[58] = " *          R1(r**2) = 6/r *((exp(r)+1)/(exp(r)-1) - 2/r)";
static const lxl_str sl6627 = {.p = sl6627b, .cap = 0U, .len = 57U};
static char sl6628b[61] = " *                   = 6/r * ( 1 + 2.0*(1/(exp(r)-1) - 1/r))";
static const lxl_str sl6628 = {.p = sl6628b, .cap = 0U, .len = 60U};
static char sl6629b[64] = " *                   = 1 - r^2/60 + r^4/2520 - r^6/100800 + ...";
static const lxl_str sl6629 = {.p = sl6629b, .cap = 0U, .len = 63U};
static char sl6630b[66] = " *      We use a special Remez algorithm on [0,0.347] to generate";
static const lxl_str sl6630 = {.p = sl6630b, .cap = 0U, .len = 65U};
static char sl6631b[63] = " *      a polynomial of degree 5 in r*r to approximate R1. The";
static const lxl_str sl6631 = {.p = sl6631b, .cap = 0U, .len = 62U};
static char sl6632b[66] = " *      maximum error of this polynomial approximation is bounded";
static const lxl_str sl6632 = {.p = sl6632b, .cap = 0U, .len = 65U};
static char sl6633b[35] = " *      by 2**-61. In other words,";
static const lxl_str sl6633 = {.p = sl6633b, .cap = 0U, .len = 34U};
static char sl6634b[71] = " *          R1(z) ~ 1.0 + Q1*z + Q2*z**2 + Q3*z**3 + Q4*z**4 + Q5*z**5";
static const lxl_str sl6634 = {.p = sl6634b, .cap = 0U, .len = 70U};
static char sl6635b[50] = " *      where   Q1  =  -1.6666666666666567384E-2,";
static const lxl_str sl6635 = {.p = sl6635b, .cap = 0U, .len = 49U};
static char sl6636b[50] = " *              Q2  =   3.9682539681370365873E-4,";
static const lxl_str sl6636 = {.p = sl6636b, .cap = 0U, .len = 49U};
static char sl6637b[50] = " *              Q3  =  -9.9206344733435987357E-6,";
static const lxl_str sl6637 = {.p = sl6637b, .cap = 0U, .len = 49U};
static char sl6638b[50] = " *              Q4  =   2.5051361420808517002E-7,";
static const lxl_str sl6638 = {.p = sl6638b, .cap = 0U, .len = 49U};
static char sl6639b[50] = " *              Q5  =  -6.2843505682382617102E-9;";
static const lxl_str sl6639 = {.p = sl6639b, .cap = 0U, .len = 49U};
static char sl6640b[28] = " *              z   =  r*r,";
static const lxl_str sl6640 = {.p = sl6640b, .cap = 0U, .len = 27U};
static char sl6641b[30] = " *      with error bounded by";
static const lxl_str sl6641 = {.p = sl6641b, .cap = 0U, .len = 29U};
static char sl6642b[53] = " *          |                  5           |     -61";
static const lxl_str sl6642 = {.p = sl6642b, .cap = 0U, .len = 52U};
static char sl6643b[50] = " *          | 1.0+Q1*z+...+Q5*z   -  R1(z) | <= 2";
static const lxl_str sl6643 = {.p = sl6643b, .cap = 0U, .len = 49U};
static char sl6644b[45] = " *          |                              |";
static const lxl_str sl6644 = {.p = sl6644b, .cap = 0U, .len = 44U};
static char sl6645b[62] = " *      expm1(r) = exp(r)-1 is then computed by the following";
static const lxl_str sl6645 = {.p = sl6645b, .cap = 0U, .len = 61U};
static char sl6646b[69] = " *      specific way which minimize the accumulation rounding error:";
static const lxl_str sl6646 = {.p = sl6646b, .cap = 0U, .len = 68U};
static char sl6647b[39] = " *                             2     3";
static const lxl_str sl6647 = {.p = sl6647b, .cap = 0U, .len = 38U};
static char sl6648b[64] = " *                            r     r    [ 3 - (R1 + R1*r/2)  ]";
static const lxl_str sl6648 = {.p = sl6648b, .cap = 0U, .len = 63U};
static char sl6649b[64] = " *            expm1(r) = r + --- + --- * [--------------------]";
static const lxl_str sl6649 = {.p = sl6649b, .cap = 0U, .len = 63U};
static char sl6650b[64] = " *                            2     2    [ 6 - r*(3 - R1*r/2) ]";
static const lxl_str sl6650 = {.p = sl6650b, .cap = 0U, .len = 63U};
static char sl6651b[66] = " *      To compensate the error in the argument reduction, we use";
static const lxl_str sl6651 = {.p = sl6651b, .cap = 0U, .len = 65U};
static char sl6652b[55] = " *              expm1(r+c) = expm1(r) + c + expm1(r)*c";
static const lxl_str sl6652 = {.p = sl6652b, .cap = 0U, .len = 54U};
static char sl6653b[48] = " *                         ~ expm1(r) + c + r*c";
static const lxl_str sl6653 = {.p = sl6653b, .cap = 0U, .len = 47U};
static char sl6654b[64] = " *      Thus c+r*c will be added in as the correction terms for";
static const lxl_str sl6654 = {.p = sl6654b, .cap = 0U, .len = 63U};
static char sl6655b[65] = " *      expm1(r+c). Now rearrange the term to avoid optimization";
static const lxl_str sl6655 = {.p = sl6655b, .cap = 0U, .len = 64U};
static char sl6656b[18] = " *      screw up:";
static const lxl_str sl6656 = {.p = sl6656b, .cap = 0U, .len = 17U};
static char sl6657b[72] = " *                      (      2                                    2 )";
static const lxl_str sl6657 = {.p = sl6657b, .cap = 0U, .len = 71U};
static char sl6658b[72] = " *                      ({  ( r    [ R1 -  (3 - R1*r/2) ]  )  }    r  )";
static const lxl_str sl6658 = {.p = sl6658b, .cap = 0U, .len = 71U};
static char sl6659b[72] = " *       expm1(r+c)~r - ({r*(--- * [--------------------]-c)-c} - --- )";
static const lxl_str sl6659 = {.p = sl6659b, .cap = 0U, .len = 71U};
static char sl6660b[72] = " *                      ({  ( 2    [ 6 - r*(3 - R1*r/2) ]  )  }    2  )";
static const lxl_str sl6660 = {.p = sl6660b, .cap = 0U, .len = 71U};
static char sl6661b[72] = " *                      (                                             )";
static const lxl_str sl6661 = {.p = sl6661b, .cap = 0U, .len = 71U};
static char sl6662b[27] = " *                 = r - E";
static const lxl_str sl6662 = {.p = sl6662b, .cap = 0U, .len = 26U};
static char sl6663b[39] = " *   3. Scale back to obtain expm1(x):";
static const lxl_str sl6663 = {.p = sl6663b, .cap = 0U, .len = 38U};
static char sl6664b[29] = " *      From step 1, we have";
static const lxl_str sl6664 = {.p = sl6664b, .cap = 0U, .len = 28U};
static char sl6665b[50] = " *         expm1(x) = either 2^k*[expm1(r)+1] - 1";
static const lxl_str sl6665 = {.p = sl6665b, .cap = 0U, .len = 49U};
static char sl6666b[55] = " *                  = or     2^k*[expm1(r) + (1-2^-k)]";
static const lxl_str sl6666 = {.p = sl6666b, .cap = 0U, .len = 54U};
static char sl6667b[30] = " *   4. Implementation notes:";
static const lxl_str sl6667 = {.p = sl6667b, .cap = 0U, .len = 29U};
static char sl6668b[69] = " *      (A). To save one multiplication, we scale the coefficient Qi";
static const lxl_str sl6668 = {.p = sl6668b, .cap = 0U, .len = 68U};
static char sl6669b[50] = " *           to Qi*2^i, and replace z by (x^2)/2.";
static const lxl_str sl6669 = {.p = sl6669b, .cap = 0U, .len = 49U};
static char sl6670b[65] = " *      (B). To achieve maximum accuracy, we compute expm1(x) by";
static const lxl_str sl6670 = {.p = sl6670b, .cap = 0U, .len = 64U};
static char sl6671b[71] = " *        (i)   if x < -56*ln2, return -1.0, (raise inexact if x!=inf)";
static const lxl_str sl6671 = {.p = sl6671b, .cap = 0U, .len = 70U};
static char sl6672b[35] = " *        (ii)  if k=0, return r-E";
static const lxl_str sl6672 = {.p = sl6672b, .cap = 0U, .len = 34U};
static char sl6673b[46] = " *        (iii) if k=-1, return 0.5*(r-E)-0.5";
static const lxl_str sl6673 = {.p = sl6673b, .cap = 0U, .len = 45U};
static char sl6674b[59] = " *        (iv)  if k=1 if r < -0.25, return 2*((r+0.5)- E)";
static const lxl_str sl6674 = {.p = sl6674b, .cap = 0U, .len = 58U};
static char sl6675b[60] = " *                     else          return  1.0+2.0*(r-E);";
static const lxl_str sl6675 = {.p = sl6675b, .cap = 0U, .len = 59U};
static char sl6676b[70] = " *        (v)   if (k<-2||k>56) return 2^k(1-(E-r)) - 1 (or exp(x)-1)";
static const lxl_str sl6676 = {.p = sl6676b, .cap = 0U, .len = 69U};
static char sl6677b[61] = " *        (vi)  if k <= 20, return 2^k((1-2^-k)-(E-r)), else";
static const lxl_str sl6677 = {.p = sl6677b, .cap = 0U, .len = 60U};
static char sl6678b[43] = " *        (vii) return 2^k(1-((E+2^-k)-r))";
static const lxl_str sl6678 = {.p = sl6678b, .cap = 0U, .len = 42U};
static char sl6679b[18] = " * Special cases:";
static const lxl_str sl6679 = {.p = sl6679b, .cap = 0U, .len = 17U};
static char sl6680b[46] = " *      expm1(INF) is INF, expm1(NaN) is NaN;";
static const lxl_str sl6680 = {.p = sl6680b, .cap = 0U, .len = 45U};
static char sl6681b[31] = " *      expm1(-INF) is -1, and";
static const lxl_str sl6681 = {.p = sl6681b, .cap = 0U, .len = 30U};
static char sl6682b[55] = " *      for finite argument, only expm1(0)=0 is exact.";
static const lxl_str sl6682 = {.p = sl6682b, .cap = 0U, .len = 54U};
static char sl6683b[13] = " * Accuracy:";
static const lxl_str sl6683 = {.p = sl6683b, .cap = 0U, .len = 12U};
static char sl6684b[70] = " *      according to an error analysis, the error is always less than";
static const lxl_str sl6684 = {.p = sl6684b, .cap = 0U, .len = 69U};
static char sl6685b[40] = " *      1 ulp (unit in the last place).";
static const lxl_str sl6685 = {.p = sl6685b, .cap = 0U, .len = 39U};
static char sl6686b[15] = " * Misc. info.";
static const lxl_str sl6686 = {.p = sl6686b, .cap = 0U, .len = 14U};
static char sl6687b[24] = " *      For IEEE double";
static const lxl_str sl6687 = {.p = sl6687b, .cap = 0U, .len = 23U};
