static char sl6789b[54] = "/* origin: FreeBSD /usr/src/lib/msun/src/s_log1p.c */";
static const lxl_str sl6789 = {.p = sl6789b, .cap = 0U, .len = 53U};
static char sl6790b[26] = "/* double log1p(double x)";
static const lxl_str sl6790 = {.p = sl6790b, .cap = 0U, .len = 25U};
static char sl6791b[40] = " * Return the natural logarithm of 1+x.";
static const lxl_str sl6791 = {.p = sl6791b, .cap = 0U, .len = 39U};
static char sl6792b[12] = " * Method :";
static const lxl_str sl6792 = {.p = sl6792b, .cap = 0U, .len = 11U};
static char sl6793b[51] = " *   1. Argument Reduction: find k and f such that";
static const lxl_str sl6793 = {.p = sl6793b, .cap = 0U, .len = 50U};
static char sl6794b[43] = " *                      1+x = 2^k * (1+f),";
static const lxl_str sl6794 = {.p = sl6794b, .cap = 0U, .len = 42U};
static char sl6795b[46] = " *         where  sqrt(2)/2 < 1+f < sqrt(2) .";
static const lxl_str sl6795 = {.p = sl6795b, .cap = 0U, .len = 45U};
