static char sl6872b[55] = "/* ---- musl 1.2.5 src/math/__rem_pio2_large.c ---- */";
static const lxl_str sl6872 = {.p = sl6872b, .cap = 0U, .len = 54U};
static char sl6873b[57] = "/* origin: FreeBSD /usr/src/lib/msun/src/k_rem_pio2.c */";
static const lxl_str sl6873 = {.p = sl6873b, .cap = 0U, .len = 56U};
static char sl6874b[60] = " * Developed at SunSoft, a Sun Microsystems, Inc. business.";
static const lxl_str sl6874 = {.p = sl6874b, .cap = 0U, .len = 59U};
static char sl6875b[36] = " * __rem_pio2_large(x,y,e0,nx,prec)";
static const lxl_str sl6875 = {.p = sl6875b, .cap = 0U, .len = 35U};
static char sl6876b[35] = " * double x[],y[]; int e0,nx,prec;";
static const lxl_str sl6876 = {.p = sl6876b, .cap = 0U, .len = 34U};
static char sl6877b[59] = " * __rem_pio2_large return the last three digits of N with";
static const lxl_str sl6877 = {.p = sl6877b, .cap = 0U, .len = 58U};
static char sl6878b[31] = " *              y = x - N*pi/2";
static const lxl_str sl6878 = {.p = sl6878b, .cap = 0U, .len = 30U};
static char sl6879b[23] = " * so that |y| < pi/2.";
static const lxl_str sl6879 = {.p = sl6879b, .cap = 0U, .len = 22U};
static char sl6880b[70] = " * The method is to compute the integer (mod 8) and fraction parts of";
static const lxl_str sl6880 = {.p = sl6880b, .cap = 0U, .len = 69U};
static char sl6881b[65] = " * (2/pi)*x without doing the full multiplication. In general we";
static const lxl_str sl6881 = {.p = sl6881b, .cap = 0U, .len = 64U};
static char sl6882b[70] = " * skip the part of the product that are known to be a huge integer (";
static const lxl_str sl6882 = {.p = sl6882b, .cap = 0U, .len = 69U};
static char sl6883b[67] = " * more accurately, = 0 mod 8 ). Thus the number of operations are";
static const lxl_str sl6883 = {.p = sl6883b, .cap = 0U, .len = 66U};
static char sl6884b[45] = " * independent of the exponent of the input.";
static const lxl_str sl6884 = {.p = sl6884b, .cap = 0U, .len = 44U};
static char sl6885b[68] = " * (2/pi) is represented by an array of 24-bit integers in ipio2[].";
static const lxl_str sl6885 = {.p = sl6885b, .cap = 0U, .len = 67U};
static char sl6886b[21] = " * Input parameters:";
static const lxl_str sl6886 = {.p = sl6886b, .cap = 0U, .len = 20U};
static char sl6887b[69] = " *      x[]     The input value (must be positive) is broken into nx";
static const lxl_str sl6887 = {.p = sl6887b, .cap = 0U, .len = 68U};
static char sl6888b[70] = " *              pieces of 24-bit integers in double precision format.";
static const lxl_str sl6888 = {.p = sl6888b, .cap = 0U, .len = 69U};
static char sl6889b[71] = " *              x[i] will be the i-th 24 bit of x. The scaled exponent";
static const lxl_str sl6889 = {.p = sl6889b, .cap = 0U, .len = 70U};
static char sl6890b[72] = " *              of x[0] is given in input parameter e0 (i.e., x[0]*2^e0";
static const lxl_str sl6890 = {.p = sl6890b, .cap = 0U, .len = 71U};
static char sl6891b[41] = " *              match x's up to 24 bits.";
static const lxl_str sl6891 = {.p = sl6891b, .cap = 0U, .len = 40U};
static char sl6892b[77] = " *              Example of breaking a double positive z into x[0]+x[1]+x[2]:";
static const lxl_str sl6892 = {.p = sl6892b, .cap = 0U, .len = 76U};
static char sl6893b[41] = " *                      e0 = ilogb(z)-23";
static const lxl_str sl6893 = {.p = sl6893b, .cap = 0U, .len = 40U};
static char sl6894b[43] = " *                      z  = scalbn(z,-e0)";
static const lxl_str sl6894 = {.p = sl6894b, .cap = 0U, .len = 42U};
static char sl6895b[30] = " *              for i = 0,1,2";
static const lxl_str sl6895 = {.p = sl6895b, .cap = 0U, .len = 29U};
static char sl6896b[40] = " *                      x[i] = floor(z)";
static const lxl_str sl6896 = {.p = sl6896b, .cap = 0U, .len = 39U};
static char sl6897b[46] = " *                      z    = (z-x[i])*2**24";
static const lxl_str sl6897 = {.p = sl6897b, .cap = 0U, .len = 45U};
static char sl6898b[70] = " *      y[]     ouput result in an array of double precision numbers.";
static const lxl_str sl6898 = {.p = sl6898b, .cap = 0U, .len = 69U};
static char sl6899b[41] = " *              The dimension of y[] is:";
static const lxl_str sl6899 = {.p = sl6899b, .cap = 0U, .len = 40U};
static char sl6900b[50] = " *                      24-bit  precision       1";
static const lxl_str sl6900 = {.p = sl6900b, .cap = 0U, .len = 49U};
static char sl6901b[50] = " *                      53-bit  precision       2";
static const lxl_str sl6901 = {.p = sl6901b, .cap = 0U, .len = 49U};
static char sl6902b[50] = " *                      64-bit  precision       2";
static const lxl_str sl6902 = {.p = sl6902b, .cap = 0U, .len = 49U};
static char sl6903b[50] = " *                      113-bit precision       3";
static const lxl_str sl6903 = {.p = sl6903b, .cap = 0U, .len = 49U};
static char sl6904b[70] = " *              The actual value is the sum of them. Thus for 113-bit";
static const lxl_str sl6904 = {.p = sl6904b, .cap = 0U, .len = 69U};
static char sl6905b[61] = " *              precison, one may have to do something like:";
static const lxl_str sl6905 = {.p = sl6905b, .cap = 0U, .len = 60U};
static char sl6906b[48] = " *              long double t,w,r_head, r_tail;";
static const lxl_str sl6906 = {.p = sl6906b, .cap = 0U, .len = 47U};
static char sl6907b[59] = " *              t = (long double)y[2] + (long double)y[1];";
static const lxl_str sl6907 = {.p = sl6907b, .cap = 0U, .len = 58U};
static char sl6908b[39] = " *              w = (long double)y[0];";
static const lxl_str sl6908 = {.p = sl6908b, .cap = 0U, .len = 38U};
static char sl6909b[30] = " *              r_head = t+w;";
static const lxl_str sl6909 = {.p = sl6909b, .cap = 0U, .len = 29U};
static char sl6910b[43] = " *              r_tail = w - (r_head - t);";
static const lxl_str sl6910 = {.p = sl6910b, .cap = 0U, .len = 42U};
static char sl6911b[70] = " *      e0      The exponent of x[0]. Must be <= 16360 or you need to";
