static const lxl_str sl6913 = {.p = sl6913b, .cap = 0U, .len = 32U};
static char sl6914b[53] = " *      prec    an integer indicating the precision:";
static const lxl_str sl6914 = {.p = sl6914b, .cap = 0U, .len = 52U};
static char sl6915b[50] = " *                      0       24  bits (single)";
static const lxl_str sl6915 = {.p = sl6915b, .cap = 0U, .len = 49U};
