static char sl6918b[48] = " *                      3       113 bits (quad)";
static const lxl_str sl6918 = {.p = sl6918b, .cap = 0U, .len = 47U};
static char sl6919b[22] = " * External function:";
static const lxl_str sl6919 = {.p = sl6919b, .cap = 0U, .len = 21U};
static char sl6920b[34] = " *      double scalbn(), floor();";
static const lxl_str sl6920 = {.p = sl6920b, .cap = 0U, .len = 33U};
static char sl6921b[52] = " * Here is the description of some local variables:";
static const lxl_str sl6921 = {.p = sl6921b, .cap = 0U, .len = 51U};
static char sl6922b[70] = " *      jk      jk+1 is the initial number of terms of ipio2[] needed";
static const lxl_str sl6922 = {.p = sl6922b, .cap = 0U, .len = 69U};
static char sl6923b[70] = " *              in the computation. The minimum and recommended value";
static const lxl_str sl6923 = {.p = sl6923b, .cap = 0U, .len = 69U};
static char sl6924b[74] = " *              for jk is 3,4,4,6 for single, double, extended, and quad.";
