static char sl6925b[72] = " *              jk+1 must be 2 larger than you might expect so that our";
static const lxl_str sl6925 = {.p = sl6925b, .cap = 0U, .len = 71U};
static char sl6926b[72] = " *              recomputation test works. (Up to 24 bits in the integer";
static const lxl_str sl6926 = {.p = sl6926b, .cap = 0U, .len = 71U};
static char sl6927b[72] = " *              part (the 24 bits of it that we compute) and 23 bits in";
static const lxl_str sl6927 = {.p = sl6927b, .cap = 0U, .len = 71U};
static char sl6928b[71] = " *              the fraction part may be lost to cancelation before we";
static const lxl_str sl6928 = {.p = sl6928b, .cap = 0U, .len = 70U};
static char sl6929b[28] = " *              recompute.)";
static const lxl_str sl6929 = {.p = sl6929b, .cap = 0U, .len = 27U};
static char sl6930b[64] = " *      jz      local integer variable indicating the number of";
static const lxl_str sl6930 = {.p = sl6930b, .cap = 0U, .len = 63U};
static char sl6931b[39] = " *              terms of ipio2[] used.";
static const lxl_str sl6931 = {.p = sl6931b, .cap = 0U, .len = 38U};
static char sl6932b[23] = " *      jx      nx - 1";
static const lxl_str sl6932 = {.p = sl6932b, .cap = 0U, .len = 22U};
static char sl6933b[67] = " *      jv      index for pointing to the suitable ipio2[] for the";
static const lxl_str sl6933 = {.p = sl6933b, .cap = 0U, .len = 66U};
static char sl6934b[49] = " *              computation. In general, we want";
static const lxl_str sl6934 = {.p = sl6934b, .cap = 0U, .len = 48U};
static char sl6935b[64] = " *                      ( 2^e0*x[0] * ipio2[jv-1]*2^(-24jv) )/8";
static const lxl_str sl6935 = {.p = sl6935b, .cap = 0U, .len = 63U};
static char sl6936b[36] = " *              is an integer. Thus";
static const lxl_str sl6936 = {.p = sl6936b, .cap = 0U, .len = 35U};
static char sl6937b[59] = " *                      e0-3-24*jv >= 0 or (e0-3)/24 >= jv";
static const lxl_str sl6937 = {.p = sl6937b, .cap = 0U, .len = 58U};
static char sl6938b[45] = " *              Hence jv = max(0,(e0-3)/24).";
static const lxl_str sl6938 = {.p = sl6938b, .cap = 0U, .len = 44U};
static char sl6939b[71] = " *      jp      jp+1 is the number of terms in PIo2[] needed, jp = jk.";
static const lxl_str sl6939 = {.p = sl6939b, .cap = 0U, .len = 70U};
static char sl6940b[67] = " *      q[]     double array with integral value, representing the";
static const lxl_str sl6940 = {.p = sl6940b, .cap = 0U, .len = 66U};
static char sl6941b[60] = " *              24-bits chunk of the product of x and 2/pi.";
static const lxl_str sl6941 = {.p = sl6941b, .cap = 0U, .len = 59U};
static char sl6942b[66] = " *      q0      the corresponding exponent of q[0]. Note that the";
static const lxl_str sl6942 = {.p = sl6942b, .cap = 0U, .len = 65U};
static char sl6943b[52] = " *              exponent for q[i] would be q0-24*i.";
static const lxl_str sl6943 = {.p = sl6943b, .cap = 0U, .len = 51U};
static char sl6944b[65] = " *      PIo2[]  double precision array, obtained by cutting pi/2";
static const lxl_str sl6944 = {.p = sl6944b, .cap = 0U, .len = 64U};
static char sl6945b[37] = " *              into 24 bits chunks.";
static const lxl_str sl6945 = {.p = sl6945b, .cap = 0U, .len = 36U};
static char sl6946b[42] = " *      f[]     ipio2[] in floating point";
static const lxl_str sl6946 = {.p = sl6946b, .cap = 0U, .len = 41U};
static char sl6947b[67] = " *      iq[]    integer array by breaking up q[] in 24-bits chunk.";
static const lxl_str sl6947 = {.p = sl6947b, .cap = 0U, .len = 66U};
static char sl6948b[61] = " *      fq[]    final product of x*(2/pi) in fq[0],..,fq[jk]";
static const lxl_str sl6948 = {.p = sl6948b, .cap = 0U, .len = 60U};
static char sl6949b[65] = " *      ih      integer. If >0 it indicates q[] is >= 0.5, hence";
